#!/usr/bin/env python3
import json

def load_config(path: str) -> dict:
    """Load configuration from a JSON file."""
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {'debug': False, 'log_level': 'INFO'}
    except Exception as e:
        raise e

# Test case for verification
def test_load_config():
    import tempfile
    import os

    # Test missing file
    with tempfile.NamedTemporaryFile(delete=False) as tmp:
        non_existent = tmp.name
    os.remove(non_existent)

    default_config = load_config(non_existent)
    assert default_config == {'debug': False, 'log_level': 'INFO'}, \
        f"Expected default config, got {default_config}"

    print('Test passed')

if __name__ == '__main__':
    test_load_config()
EOF

